    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address newOwner) public {
        require(newOwner != address(0), "new owner must be non-zero to avoid revert");

        c.transferOwnership(newOwner);
        address ownerAfterTransfer = c.owner();

        c.renounceOwnership();
        address ownerAfterRenounce = c.owner();

        assert(ownerAfterTransfer == newOwner && ownerAfterRenounce == address(0));
    }
