contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newImpl) public {
        address before = c.roundImplementation();

        bool reverted;
        if (newImpl == address(0)) {
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.roundImplementation() == before);
        } else {
            // A fresh C is owned by this test contract, so the call should succeed.
            try c.updateRoundImplementation(payable(newImpl)) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.roundImplementation() == newImpl);
        }
    }
}

